# Toy group with sender keys, not for production. Who gets my sender key?
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey as Ed
from cryptography.exceptions import InvalidSignature
admin = Ed.generate()                           # the group admin's identity key
trusted_admins = [admin.public_key()]           # learned when the group was made

def signed_change(signer, change):
    return change, signer.sign(change)

def vulnerable_members(server_list):
    return server_list                          # BUG: the server decides who is in

def checked_members(current, changes):
    members = set(current)
    for change, sig in changes:
        if not any(_ok(pk, sig, change) for pk in trusted_admins):
            print("  rejected unsigned change:", change.decode())
            continue
        members.add(change.decode().removeprefix("add:"))
    return members

def _ok(pk, sig, msg):
    try:
        pk.verify(sig, msg); return True
    except InvalidSignature:
        return False

current = {"ana", "bob", "cy"}
legit = signed_change(admin, b"add:di")
forged = (b"add:mallory", b"\0" * 64)           # the server cannot sign as admin
print("vulnerable sends key to:", sorted(vulnerable_members(current | {"mallory"})))
print("checked client:")
print("  sends key to:", sorted(checked_members(current, [legit, forged])))
